patch:
diff --git a/repro-no-var-tdz.mjs b/repro-no-var-tdz.mjs
new file mode 100644
index 0000000..20732e0
--- /dev/null
+++ b/repro-no-var-tdz.mjs
@@ -0,0 +1,22 @@
+import vm from "node:vm";
+import { Linter } from "./lib/api.js";
+const linter = new Linter();
+const cases = {
+  "report": "function a() {
    console.log(o);
    var o;
    return o;
}
a();",
+  "f.call": "function a() {
    f.call(null);
    var o;
    function f() { return o; }
}
a();",
+  "new f": "function a() {
    new f();
    var o;
    function f() { return o; }
}
a();",
+  "tagged": "function a() {
    f``;
    var o;
    function f() { return o; }
}
a();",
+  "map(f)": "function a() {
    [1].map(f);
    var o;
    function f() { return o; }
}
a();",
+  "(0,f)()": "function a() {
    (0, f)();
    var o;
    function f() { return o; }
}
a();",
+  "transitive": "function a() {
    g();
    var o;
    function f() { return o; }
    function g() { return f(); }
}
a();",
+  "direct call (control)": "function a() {
    f();
    var o;
    function f() { return o; }
}
a();",
+};
+let broken = 0;
+for (const [k, code] of Object.entries(cases)) {
+  const r = linter.verifyAndFix(code, [{ rules: { "no-var": "error" } }]);
+  let run = (c) => { try { vm.runInNewContext(c, { console: { log() {} } }); return "ok"; } catch (e) { return e.name + ": " + e.message; } };
+  if (run(code) === "ok" && run(r.output) !== "ok") broken++;
+  console.log(`${k.padEnd(22)} fixed=${String(r.fixed).padEnd(5)} before: ${run(code).padEnd(8)} after: ${run(r.output)}`);
+}
+console.log(`
${broken} case(s) where the no-var autofix turns working code into a ReferenceError`);
+process.exitCode = broken ? 1 : 0;
